# Let me try to find any information about budget projections for 2025
# by looking at what type of "estimates" are discussed in the narrative

# Read all bulletins and extract any numbers associated with 2025
import os
import re

all_2025_mentions = []
for root, dirs, files in os.walk('/app/resources'):
    for f in files:
        if f.endswith('.txt') and not f.startswith('.'):
            filepath = os.path.join(root, f)
            try:
                with open(filepath, 'r', errors='ignore') as file:
                    content = file.read()

                # Find all mentions of 2025
                if '2025' in content:
                    lines = content.split('\n')
                    for i, line in enumerate(lines):
                        if '2025' in line:
                            # Extract any numbers from the line
                            numbers = re.findall(r'-?\$?\d+(?:,\d+)*', line)
                            if numbers:
                                all_2025_mentions.append((f, i, line.strip()[:120], numbers))
            except:
                pass

print("All lines with 2025 and numbers:")
for f, i, line, numbers in all_2025_mentions:
    print(f"\n{f} line {i}:")
    print(f"  {line}")
    print(f"  Numbers found: {numbers}")
EOF
